const ALL_COLS=[["name","Name"],["description","Description"],["category","Category"],["archetype","Archetype"],["subClassification","Sub-class"],["appTechnology","Technology"],["database","Database"],["dtdOwner","DTD Owner"],["businessOwner","Biz Owner"],["mau","MAU"],["primaryUserType","User Type"],["geographicReach","Geo Reach"],["portfolio","Portfolio"],["department","Department"],["totalAnnualCost","Total Cost"],["capitalCost","Capital Cost"],["operationalCost","Op. Cost"],["size","Size"],["strategyReco","Strategy"],["status","Status"],["costCenter","Cost Center"],["fundingOrigin","Funding"],["financialSustainability","Fin.Sust."],["keepLightsOn","KTLO"],["strategicPositioning","Strategic"],["geographicReachScore","Geo Score"],["currentHumReach","Impact"],["potentialFutureValue","Future Val"],["comments","Comments"],["userNotes","Notes"]];
